#pragma once
static void checkMetalExpansionLayout(App& app,const std::string& dir){
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("metal expansion layout: "+why);};auto& s=app.s;int cases=0;
    for(const char* font:{"Times New Roman","Arial"})for(double unit:{22.,14.4})for(double angle:{0.,30.,90.,150.,210.,270.})for(bool stored:{false,true}){
        s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.doc.setDefaultBondLength(unit);s.doc.setDefaultFont(font);s.doc.documentExtensions().set("studio.style.LabelFontName",font);s.doc.documentExtensions().set("studio.style.LabelSize","10");
        ObjectId metal,host,left,top,external;s.doc.addAtom(Vec2(),6,&metal);auto hp=direction(angle)*unit;s.doc.addAtom(hp,6,&host);s.doc.addAtom(hp+direction(angle+60)*unit,6,&left);s.doc.addAtom(hp+direction(angle-60)*unit,6,&top);s.doc.addBond(metal,host,&external);s.doc.addBond(host,left,nullptr);s.doc.addBond(host,top,nullptr);
        if(stored)require(s.submit(nicknames::labelCommand(metal,"PdCl2"),"原子快捷键").ok(),"library-backed input");else {s.doc.setAtomLabel(metal,"PdCl2");auto sem=s.doc.atoms().alive(metal)->semantics;sem.nodeType=uint8_t(NodeType::Query);sem.showLabel=true;s.doc.setAtomSemantics(metal,sem);}
        auto plan=functional_groups::prepareExpansion(s.doc,metal);require(plan.metalLigands&&plan.graph->atoms().alive(plan.anchor)->element==46,"same metal path for text and stored templates");
        s.refresh();s.selected={{ObjectKind::Atom,metal}};auto before=s.doc.digest();app.expandPending=false;app.expandGroups();require(s.doc.atoms().alive(metal)->element==46&&s.doc.incidentBonds(metal).size()==3,"Pd retains scaffold and two chlorides");
        require(s.doc.atoms().alive(metal)->position==Vec2()&&s.doc.atoms().alive(host)->position==hp&&s.doc.atoms().alive(left)->position==hp+direction(angle+60)*unit&&s.doc.atoms().alive(top)->position==hp+direction(angle-60)*unit,"original scaffold fixed");
        std::vector<Vec2> rays{direction(angle)};std::vector<ObjectId> chlorides;
        for(auto bid:s.doc.incidentBonds(metal)){auto b=s.doc.bonds().alive(bid);auto id=b->beginAtom==metal?b->endAtom:b->beginAtom;if(id==host)continue;require(s.doc.atoms().alive(id)->element==17,"chloride is a real atom");auto v=s.doc.atoms().alive(id)->position;require(length(v)>=unit-1e-6&&length(v)<unit*2.5,"reasonable label-aware ligand length");rays.push_back(v*(1/length(v)));chlorides.push_back(id);require(metal_expansion_layout::visibleBond(s.doc,metal,id,s.glyphs)>=unit*.4,"Pd-Cl is a visible bond rather than a dash");}
        for(size_t i=0;i<rays.size();++i)for(size_t j=0;j<i;++j)require(std::abs(dot(rays[i],rays[j])+.5)<1e-6,"new chlorides use the free trigonal directions");
        auto labels=integration::molecular::labels(s.doc,s.glyphs,integration::RingGeometry(s.doc));for(auto id:chlorides)for(const auto& other:labels)if(other.first!=id){auto a=labels.at(id).box,b=other.second.box;double x=std::min(a.max.x,b.max.x)-std::max(a.min.x,b.min.x),y=std::min(a.max.y,b.max.y)-std::max(a.min.y,b.min.y);require(x<=0||y<=0,"metal and ligand ink boxes do not overlap");}
        auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before&&s.undo(true).ok()&&s.doc.digest()==after,"one undo/redo includes coordination layout");
        if(stored&&unit==14.4&&angle==210.&&std::string(font)=="Arial"){s.selected.clear();s.fit();require(s.save(dir+"/attached-pdcl2-clean.cdxml",true).ok(),"save user case");app.screenshot(dir+"/attached-pdcl2-clean.png",false,false);Session back;require(back.open(dir+"/attached-pdcl2-clean.cdxml").ok(),"reopen user case");for(auto id:chlorides)require(metal_expansion_layout::visibleBond(back.doc,metal,id,back.glyphs)>=unit*.4,"clearance survives export");}
        ++cases;
    }
    int complexes=0;for(const char* label:{"PtCl2","RuCl2","NiCl2(PPh3)2","PdCl2(PPh3)2","Ni(CO)4","RuLn"}){
        s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.doc.setDefaultBondLength(22);ObjectId metal,host,edge;s.doc.addAtom(Vec2(),6,&metal);s.doc.addAtom(Vec2(-19.052558883,-11),6,&host);s.doc.addBond(host,metal,&edge);s.refresh();app.openText(kInvalidObjectId,metal);SetWindowTextW(app.edit,W(label).c_str());require(app.finishText(true),std::string("complex input: ")+label);auto plan=functional_groups::prepareExpansion(s.doc,metal);auto expected=plan.graph->stats();auto element=plan.graph->atoms().alive(plan.anchor)->element;s.refresh();s.selected={{ObjectKind::Atom,metal}};auto before=s.doc.digest();app.expandPending=false;app.expandGroups();require(s.doc.atoms().alive(metal)->element==element&&s.doc.bondBetween(host,metal)==edge,"complex attaches through actual metal");require(s.doc.stats().aliveAtoms==expected.aliveAtoms+1&&s.doc.stats().aliveBonds==expected.aliveBonds+1,"ligand graph is retained in full");for(const auto& atom:s.doc.atoms().records())if(atom.isAlive()&&atom.semantics.nodeType==uint8_t(NodeType::Query))require(!s.doc.atomLabel(atom.id).empty(),"generic ligand text remains visible");auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before&&s.undo(true).ok()&&s.doc.digest()==after,"complex layout undo/redo");++complexes;
    }
    std::ofstream(dir+"/metal-expansion-layout-checks.json")<<"{\"pdcl2_cases\":"<<cases<<",\"other_complexes\":"<<complexes<<",\"library_and_text\":true,\"scaffold_fixed\":true,\"visible_bonds\":true,\"no_label_overlap\":true,\"undo_redo\":true,\"cdxml\":true}";
}
